jQuery(document).ready(function ($) {
    "use strict";

    function normalizeVi(str) {
        return String(str || "")
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .replace(/đ/g, "d")
            .replace(/Đ/g, "D")
            .toLowerCase();
    }

    var realnessCatalog = [
        { value: "Green Skyline — TBS Land (Quốc lộ 1K, Dĩ An)", url: "/du-an/green-skyline/", price: "Dự án • 3.5 – 12 Tỷ", keywords: "green skyline tbs land di an binh duong can ho studio 1pn 2pn 3pn duplex shophouse" },
        { value: "Palm River — Quận 2, TP. Thủ Đức", url: "/du-an/palm-river/", price: "Dự án • Khu Đông", keywords: "palm river quan 2 thu duc nam rach chiec" },
        { value: "The Privé An Phú — Đất Xanh Group (TP. Thủ Đức)", url: "/du-an/the-prive/", price: "Dự án • An Phú", keywords: "the prive an phu dat xanh thu duc gem riverside" },
        { value: "Eaton Park — Gamuda Land (Mai Chí Thọ, TP. Thủ Đức)", url: "/du-an/eaton-park/", price: "Dự án • Mai Chí Thọ", keywords: "eaton park gamuda land mai chi tho an phu thu duc" },
        { value: "The Global City — Masterise Homes (An Phú, TP. Thủ Đức)", url: "/du-an/the-global-city/", price: "Đại đô thị • Khu Đông", keywords: "the global city masterise homes an phu thu duc" },
        { value: "Vlasta Premier — Phú Thuận, Quận 7", url: "/du-an/vlasta-premier/", price: "Dự án • Khu Nam", keywords: "vlasta premier van phu invest quan 7 khu nam" },
        { value: "Happy One Elite — Vạn Xuân Group", url: "/du-an/happy-one-elite/", price: "Dự án • Căn hộ", keywords: "happy one elite van xuan binh duong" },
        { value: "TT Genesis — TT Capital", url: "/du-an/tt-genesis/", price: "Dự án • Căn hộ", keywords: "tt genesis tt capital di an binh duong" },
        { value: "The Opus One — Vinhomes Grand Park", url: "/du-an/the-opus-one/", price: "Dự án • Khu Đông", keywords: "the opus one vinhomes grand park thu duc" },
        { value: "Celesta Heights — Keppel Land (Nam Sài Gòn)", url: "/du-an/celesta-heights/", price: "Dự án • Khu Nam", keywords: "celesta heights keppel land nha be nam sai gon" },
        { value: "King Crown Infinity — BCG Land (Võ Văn Ngân, Thủ Đức)", url: "/du-an/king-crown-infinity/", price: "Dự án • Thủ Đức", keywords: "king crown infinity bcg land vo van ngan thu duc" },
        { value: "Sycamore Bình Dương — CapitaLand", url: "/du-an/sycamore-binh-duong/", price: "Dự án • Bình Dương", keywords: "sycamore binh duong capitaland thanh pho moi" },
        { value: "Danh mục tất cả Dự án trên Realness.vn", url: "/du-an/", price: "Toàn bộ dự án", keywords: "du an bat dong san can ho chung cu realness" },
        { value: "Góc Phân Tích & Dữ Liệu Bất Động Sản Realness", url: "/phan-tich/", price: "Chuyên mục Phân tích", keywords: "phan tich danh gia thi truong bat dong san phap ly gia ban" },
        { value: "Công cụ tính Khả năng chi trả & Dòng tiền vay mua nhà", url: "/cong-cu/kha-nang-chi-tra/", price: "Công cụ tài chính", keywords: "cong cu tinh vay ngan hang lai suat dong tien kha nang chi tra" },
        { value: "Phương pháp thẩm định & Dữ liệu minh bạch Realness", url: "/phuong-phap/", price: "Phương pháp Realness", keywords: "phuong phap tham dinh du lieu minh bach realness" },
        { value: "Mặt bằng & Thiết kế căn hộ Green Skyline", url: "#matbang", price: "Mục trong trang", keywords: "mat bang thiet ke studio 1pn 2pn 3pn green skyline" },
        { value: "Vị trí & Kết nối vùng Green Skyline", url: "#vitri", price: "Mục trong trang", keywords: "vi tri ket noi quoc lo 1k bigc go di an green skyline" },
        { value: "68+ Tiện ích nội khu Resort Green Skyline", url: "#tienich", price: "Mục trong trang", keywords: "tien ich ho boi cong vien resort green skyline" },
        { value: "Tiến độ xây dựng thực tế Green Skyline", url: "#tiendo", price: "Mục trong trang", keywords: "tien do xay dung ban giao green skyline" }
    ];

    $('.searchform').each(function () {
        var $form = $(this);
        var append = $form.find('.live-search-results');

        $form.on('submit', function (e) {
            e.preventDefault();
            var q = $.trim($form.find('.search-field').val() || '');
            window.location.href = '/tim-kiem?s=' + encodeURIComponent(q);
        });

        $form.find('.search-field').devbridgeAutocomplete({
            minChars: 1,
            appendTo: append,
            triggerSelectOnValidInput: false,
            deferRequestBy: 80,
            lookup: function (query, done) {
                var normQ = normalizeVi(query);
                var words = normQ.split(/\s+/).filter(Boolean);
                var matches = $.grep(realnessCatalog, function (item) {
                    var hay = normalizeVi(item.value + ' ' + item.keywords + ' ' + item.price);
                    for (var i = 0; i < words.length; i++) {
                        if (hay.indexOf(words[i]) === -1) return false;
                    }
                    return true;
                });
                matches.push({
                    id: "search-all",
                    value: 'Xem tất cả kết quả cho "' + query + '" trên Realness.vn',
                    url: '/tim-kiem?s=' + encodeURIComponent(query),
                    price: 'Tìm toàn trang Realness.vn →'
                });
                done({ suggestions: matches.slice(0, 8) });
            },
            onSelect: function (suggestion) {
                if (suggestion && suggestion.url) {
                    if (suggestion.url.charAt(0) === '#' && $.magnificPopup) {
                        $.magnificPopup.close();
                    }
                    window.location.href = suggestion.url;
                }
            },
            beforeRender: function (container) {
                $(container).removeAttr('style');
            },
            formatResult: function (suggestion, currentValue) {
                var pattern = '(' + $.Autocomplete.utils.escapeRegExChars(currentValue) + ')';
                var html = '<div class="search-name" style="font-weight:600;color:#0b3b28;">' +
                    suggestion.value.replace(new RegExp(pattern, 'gi'), '<strong>$1<\/strong>') +
                    '</div>';
                if (suggestion.price) {
                    html += '<span class="search-price" style="font-size:12px;color:#8a6d2b;">' + suggestion.price + '</span>';
                }
                return html;
            }
        });
    });
});
